 internal void SetWeakCycleMode(int cycles){WeakSettings.ClearCycles=Math.Clamp(cycles,0,2);cycleGroup=lastCycle=null;}
 internal void BeginWeakCycle(string source,long slot,string mode,long epoch)
 {
  if(weakPreferences==null||weakPreferences.ClearCycles==0)return;string key=source+"|"+mode+"|"+epoch;long group=slot/weakPreferences.ClearCycles;if(key==cycleSource&&lastCycle.HasValue&&slot<=lastCycle)return;if(cycleGroup!=null&&(key!=cycleSource||cycleGroup!=group))ClearRows();cycleSource=key;cycleGroup=group;lastCycle=slot;
 }
 private void ObserveWeak(PacketObservation p){if(weakPreferences==null)return;var d=p.Weak;if(d.Slot is long slot)BeginWeakCycle(p.SourceKey??p.Source,slot,p.Protocol,d.Epoch);weakTracking.Observe(p);trackingGrid?.Items.Refresh();}
